mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/Scratch.java" <<'EOF'
import org.apache.commons.lang3.text.ExtendedMessageFormat;
import org.apache.commons.lang3.text.FormatFactory;
import java.text.Format;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class Scratch {
    public static void main(String[] args) throws Exception {
        try {
            new ExtendedMessageFormat((String) null);
        } catch (Exception e) {
            System.out.println("null pattern -> " + e.getClass().getName() + ": " + e.getMessage());
        }

        try {
            ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,upper,foo");
            Map<String, FormatFactory> reg = new HashMap<String, FormatFactory>();
            reg.put("upper", new FormatFactory() {
                public Format getFormat(String name, String arguments, Locale locale) {
                    return null;
                }
            });
        } catch (Exception e) {
            System.out.println("unterminated -> " + e.getClass().getName() + ": " + e.getMessage());
        }

        Map<String, FormatFactory> reg = new HashMap<String, FormatFactory>();
        reg.put("upper", new FormatFactory() {
            public Format getFormat(String name, String arguments, Locale locale) {
                return new java.text.Format() {
                    public StringBuffer format(Object obj, StringBuffer toAppendTo, java.text.FieldPosition pos) {
                        return toAppendTo.append(String.valueOf(obj).toUpperCase());
                    }
                    public Object parseObject(String source, java.text.ParsePosition pos) {
                        return null;
                    }
                };
            }
        });
        ExtendedMessageFormat emf2 = new ExtendedMessageFormat("Hi {0,upper}!", reg);
        System.out.println("formatted: " + emf2.format(new Object[]{"bob"}));
        System.out.println("toPattern: " + emf2.toPattern());

        ExtendedMessageFormat emfPlain = new ExtendedMessageFormat("Hello, {0}!");
        System.out.println("plain toPattern: " + emfPlain.toPattern());
        System.out.println("plain format: " + emfPlain.format(new Object[]{"World"}));

        try {
            new ExtendedMessageFormat("{0");
        } catch (Exception e) {
            System.out.println("bad index -> " + e.getClass().getName() + ": " + e.getMessage());
        }

        try {
            emfPlain.setFormat(0, null);
        } catch (Exception e) {
            System.out.println("setFormat -> " + e.getClass().getName());
        }

        ExtendedMessageFormat a1 = new ExtendedMessageFormat("x {0}", Locale.US);
        ExtendedMessageFormat a2 = new ExtendedMessageFormat("x {0}", Locale.US);
        System.out.println("equals same: " + a1.equals(a2));
        System.out.println("hashcode same: " + (a1.hashCode() == a2.hashCode()));
        ExtendedMessageFormat a3 = new ExtendedMessageFormat("x {0}", Locale.FRANCE);
        System.out.println("equals diff locale: " + a1.equals(a3));

        System.out.println("equals null: " + a1.equals(null));
        System.out.println("equals string: " + a1.equals("x {0}"));

        ExtendedMessageFormat choice = new ExtendedMessageFormat("{0,choice,0#no|1#one|1<many}");
        System.out.println("choice toPattern: " + choice.toPattern());
        System.out.println("choice format 0: " + choice.format(new Object[]{Integer.valueOf(0)}));
        System.out.println("choice format 2: " + choice.format(new Object[]{Integer.valueOf(2)}));

        ExtendedMessageFormat quoted = new ExtendedMessageFormat("It''s a {0} day", reg);
        System.out.println("quoted toPattern: " + quoted.toPattern());
        System.out.println("quoted format: " + quoted.format(new Object[]{"sunny"}));
    }
}
EOF
javac -cp target/classes -d "$TMPDIR/scratch" "$TMPDIR/scratch/Scratch.java" && java -cp "target/classes:$TMPDIR/scratch" Scratch
